import { useEffect, useMemo, useState } from "react"
import type { RouteConfig } from "@mercurjs/dashboard-sdk"
import { Button, Card, Empty, Field, FormGrid, Page, PageHeader } from "../../spike/ui"
import {Input} from "../../components/ui/input"
import {Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from "../../components/ui/table"
declare const __BACKEND_URL__: string
export const config: RouteConfig = { label: "التقارير", rank: 81 }
const n=(x:any)=>Number(x?.value ?? x ?? 0)||0
const money=(x:number,c="SAR")=>`${x.toFixed(2)} ${c}`
const download=(rows:any[])=>{const headers=["رقم الطلب","التاريخ","الإجمالي","العمولة","الصافي","العملة"];const csv=[headers.join(","),...rows.map(r=>[r.display_id||r.id,new Date(r.created_at).toLocaleDateString("ar"),r.total,r.commission,r.net,r.currency_code].map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(","))].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));a.download=`spike-vendor-report-${Date.now()}.csv`;a.click();URL.revokeObjectURL(a.href)}
export default function VendorReports(){const [orders,setOrders]=useState<any[]>([]); const [commission,setCommission]=useState(0); const [from,setFrom]=useState("");const [to,setTo]=useState("");useEffect(()=>{fetch(`${__BACKEND_URL__}/vendor/orders?limit=500`,{credentials:"include"}).then(r=>r.json()).then(d=>setOrders(d.orders||[])).catch(()=>{});fetch(`${__BACKEND_URL__}/vendor/spike/exchange-rates`,{credentials:"include"}).then(r=>r.json()).then(d=>setCommission(n(d.settings?.commission_percent))).catch(()=>{})},[]);const rows=useMemo(()=>orders.filter(o=>(!from||new Date(o.created_at)>=new Date(from))&&(!to||new Date(o.created_at)<=new Date(to+"T23:59:59"))).map(o=>{const total=n(o.total);const com=total*commission/100;return {...o,total,commission:com,net:total-com}}),[orders,from,to,commission]);const total=rows.reduce((a,r)=>a+r.total,0), com=rows.reduce((a,r)=>a+r.commission,0), net=rows.reduce((a,r)=>a+r.net,0), cur=rows[0]?.currency_code?.toUpperCase()||"SAR";return <Page><PageHeader title="تقارير المبيعات" description={`عمولة Spike الحالية: ${commission}%`} actions={<Button onClick={()=>download(rows)}>تصدير Excel / CSV</Button>}/><Card><FormGrid><Field label="من"><Input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="إلى"><Input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></FormGrid><div className="grid gap-3 md:grid-cols-4">{[['المبيعات',money(total,cur)],['عمولة Spike',money(com,cur)],['صافي المستحق',money(net,cur)],['الطلبات',String(rows.length)]].map(([label,value])=><Card key={label}><span className="text-sm text-muted-foreground">{label}</span><b className="mt-2 block text-xl">{value}</b></Card>)}</div></Card><Card>{rows.length?<Table><TableHeader><TableRow><TableHead>الطلب</TableHead><TableHead>التاريخ</TableHead><TableHead>الإجمالي</TableHead><TableHead>العمولة</TableHead><TableHead>الصافي</TableHead></TableRow></TableHeader><TableBody>{rows.slice(0,100).map(r=><TableRow key={r.id}><TableCell>#{r.display_id||r.id}</TableCell><TableCell>{new Date(r.created_at).toLocaleDateString("ar")}</TableCell><TableCell>{money(r.total,cur)}</TableCell><TableCell>{money(r.commission,cur)}</TableCell><TableCell>{money(r.net,cur)}</TableCell></TableRow>)}</TableBody></Table>:<Empty>لا توجد بيانات ضمن الفترة المحددة.</Empty>}</Card></Page>}
